/**
 * LATTICE — Shechtman's "impossible" crystal under precession electron
 * diffraction.
 *
 * The reciprocal lattice of an icosahedral quasicrystal seen down a 5-fold
 * zone axis is generated by cut-and-project from five integer indices:
 * g∥ = Σ nⱼ eⱼ with eⱼ at 72° steps, while the perpendicular-space component
 * g⊥ = Σ nⱼ e⊥ⱼ (angles doubled) sets the intensity envelope exp(−κ|g⊥|²).
 * The result is the 10-fold pattern no periodic crystal can produce, with
 * spot spacings in the golden ratio τ = 1.618…
 *
 * The beam precesses on a 1.5° cone, so the Ewald sphere cuts the zero-order
 * plane along a Laue circle through the origin that sweeps around the
 * pattern; spots flare as the circle crosses them and fade with phosphor
 * afterglow. Each tool call indexes a live reflection with its five indices
 * and d-spacing; a failed call spreads the mosaic and smears spots red.
 */
import { at, clamp, mixHex, rgba } from '../palette.ts'
import {
  age, backdrop, decode, EventTrack, font, footer, TAU,
  type SceneFrame, type ScenePainter,
} from '../paint.ts'

/** Golden ratio. */
export const PHI = (1 + Math.sqrt(5)) / 2
/** Quasilattice constant used to put the pattern in physical units (Å). */
const A_R = 4.6
const G_MAX = 3.3
const LAUE_D = G_MAX * 0.92

/** One reflection of the 5-fold zone. */
export interface Reflection {
  /** Five cut-and-project indices. */
  n: readonly number[]
  /** In-plane reciprocal vector (units of the basis). */
  gx: number
  /** In-plane reciprocal vector (units of the basis). */
  gy: number
  /** |g∥|. */
  g: number
  /** Kinematic intensity envelope. */
  I0: number
}

/**
 * Build the 5-fold zone of the icosahedral reciprocal lattice.
 * @returns reflections sorted by |g|, one per distinct g∥.
 */
export function quasicrystalZone(): Reflection[] {
  const ex = Array.from({ length: 5 }, (_, j) => Math.cos(TAU * j / 5))
  const ey = Array.from({ length: 5 }, (_, j) => Math.sin(TAU * j / 5))
  const px = Array.from({ length: 5 }, (_, j) => Math.cos(2 * TAU * j / 5))
  const py = Array.from({ length: 5 }, (_, j) => Math.sin(2 * TAU * j / 5))
  const seen = new Map<string, Reflection>()
  const n = [0, 0, 0, 0, 0]
  for (let k = 0; k < 16807; k++) {
    let rest = k
    for (let j = 0; j < 5; j++) {
      n[j] = (rest % 7) - 3
      rest = Math.floor(rest / 7)
    }
    let gx = 0
    let gy = 0
    let qx = 0
    let qy = 0
    for (let j = 0; j < 5; j++) {
      gx += at(n, j) * at(ex, j)
      gy += at(n, j) * at(ey, j)
      qx += at(n, j) * at(px, j)
      qy += at(n, j) * at(py, j)
    }
    const g = Math.hypot(gx, gy)
    if (g < 1e-6 || g > G_MAX) continue
    const I0 = Math.exp(-0.75 * (qx * qx + qy * qy))
    if (I0 < 0.012) continue
    const key = `${Math.round(gx * 1e4)},${Math.round(gy * 1e4)}`
    const prev = seen.get(key)
    if (prev === undefined || prev.I0 < I0) seen.set(key, { n: [...n], gx, gy, g, I0 })
  }
  return [...seen.values()].sort((a, b) => a.g - b.g)
}

const ZONE = quasicrystalZone()
const ICOSA = (() => {
  const v: [number, number, number][] = []
  for (const a of [-1, 1]) {
    for (const b of [-1, 1]) v.push([0, a, b * PHI], [a, b * PHI, 0], [b * PHI, 0, a])
  }
  const edges: [number, number][] = []
  for (let i = 0; i < v.length; i++) {
    for (let j = i + 1; j < v.length; j++) {
      const d = Math.hypot(at(v, i)[0] - at(v, j)[0], at(v, i)[1] - at(v, j)[1], at(v, i)[2] - at(v, j)[2])
      if (Math.abs(d - 2) < 1e-6) edges.push([i, j])
    }
  }
  return { v, edges }
})()

/**
 * Golden-ratio check along the e₀ row: successive |g| ratios of the brightest
 * spots on the positive x axis.
 * @returns the ratios between consecutive strong spots.
 */
export function rowRatios(): number[] {
  const row = ZONE.filter(r => Math.abs(r.gy) < 1e-6 && r.gx > 0 && r.I0 > 0.4).map(r => r.g)
  return row.slice(1).map((g, i) => g / at(row, i))
}

/**
 * Create the LATTICE painter.
 * @returns a stateful painter.
 */
export function createLatticeScene(): ScenePainter<'lattice'> {
  const acc = new Float32Array(ZONE.length)
  const index = new EventTrack<{ ri: number }>(3)
  let primed = false
  return (f: SceneFrame<'lattice'>): void => {
    const { c, w, h, P, s, A, now, still } = f
    const ms = Math.max(s, 0.55)
    const errK = f.sm('err', age(A.errT, now) < 1.8 ? 1 : 0, 3)
    const cx = w * 0.7
    const cy = h * 0.47
    const R = Math.min(w * 0.3, h * 0.44)
    const scale = R / G_MAX
    backdrop(c, w, h, P, cx, cy, R * 1.6, P.phosphor, 0.08)
    // Viewing screen, camera ticks, and zone label.
    c.lineWidth = 1
    c.strokeStyle = rgba(P.grid, 0.3)
    c.beginPath()
    c.arc(cx, cy, R * 1.08, 0, TAU)
    c.stroke()
    c.strokeStyle = rgba(P.grid, 0.22)
    c.beginPath()
    for (let j = 0; j < 120; j++) {
      const a = j * TAU / 120
      const r2 = R * (j % 10 === 0 ? 1.14 : 1.11)
      c.moveTo(cx + Math.cos(a) * R * 1.08, cy + Math.sin(a) * R * 1.08)
      c.lineTo(cx + Math.cos(a) * r2, cy + Math.sin(a) * r2)
    }
    c.stroke()
    c.strokeStyle = rgba(P.grid, 0.1)
    c.beginPath()
    for (let j = 0; j < 10; j++) {
      const a = j * TAU / 10
      c.moveTo(cx, cy)
      c.lineTo(cx + Math.cos(a) * R * 1.08, cy + Math.sin(a) * R * 1.08)
    }
    c.stroke()

    // Precession: the Laue circle (diameter LAUE_D) turns about the origin.
    const phiP = A.ph * 1.25
    const ux = Math.cos(phiP)
    const uy = Math.sin(phiP)
    const sig = 0.07 * (1 + errK * 2.5)
    const lit = (r: Reflection, cu: number, su: number): number => {
      const se = (r.gx * cu + r.gy * su) - r.g * r.g / LAUE_D
      return r.I0 * Math.exp(-((se / sig) ** 2))
    }
    if (still || !primed) {
      ZONE.forEach((r, i) => {
        let best = 0
        for (let q = 0; q < 36; q++) best = Math.max(best, lit(r, Math.cos(q * TAU / 36), Math.sin(q * TAU / 36)))
        acc[i] = still ? best : best * 0.35
      })
      primed = true
    } else {
      const decay = Math.exp(-f.dt / 2.4)
      ZONE.forEach((r, i) => { acc[i] = Math.max(at(acc, i) * decay, lit(r, ux, uy)) })
    }
    if (!still) {
      c.setLineDash([3, 5])
      c.strokeStyle = rgba(P.accent, 0.35)
      c.beginPath()
      c.arc(cx + ux * LAUE_D / 2 * scale, cy - uy * LAUE_D / 2 * scale, LAUE_D / 2 * scale, 0, TAU)
      c.stroke()
      c.setLineDash([])
    }
    const pos = (r: Reflection): [number, number] => [cx + r.gx * scale, cy - r.gy * scale]
    ZONE.forEach((r, i) => {
      const a = at(acc, i)
      if (a < 0.015) return
      const [x, y] = pos(r)
      const col = mixHex(r.n.reduce((p, q) => p + Math.abs(q), 0) % 2 ? P.spot2 : P.accent, P.err, errK)
      const Rs = (0.9 + 3 * Math.sqrt(a)) * ms
      if (errK > 0.02) {
        const ang = Math.atan2(y - cy, x - cx)
        const rad = Math.hypot(x - cx, y - cy)
        c.strokeStyle = rgba(col, 0.5 * a * errK)
        c.lineWidth = Rs
        c.beginPath()
        c.arc(cx, cy, rad, ang - 0.07 * errK, ang + 0.07 * errK)
        c.stroke()
        c.lineWidth = 1
      }
      const g = c.createRadialGradient(x, y, 0, x, y, Rs * 2.4)
      g.addColorStop(0, rgba(col, Math.min(1, 0.3 + a)))
      g.addColorStop(0.35, rgba(col, 0.45 * a))
      g.addColorStop(1, rgba(col, 0))
      c.fillStyle = g
      c.beginPath()
      c.arc(x, y, Rs * 2.4, 0, TAU)
      c.fill()
      if (a > 0.45) {
        c.strokeStyle = rgba(col, 0.4 * a)
        c.beginPath()
        c.moveTo(x - Rs * 3.4, y)
        c.lineTo(x + Rs * 3.4, y)
        c.moveTo(x, y - Rs * 3.4)
        c.lineTo(x, y + Rs * 3.4)
        c.stroke()
      }
    })
    // Transmitted beam and beam stop.
    c.fillStyle = rgba(P.ink, 0.6)
    c.beginPath()
    c.arc(cx, cy, R * 0.05, 0, TAU)
    c.fill()
    c.fillRect(cx, cy - 2 * ms, R * 1.4, 4 * ms)

    // Golden-ratio ruler along e₀.
    const labels = w > 420
    const row = ZONE.filter(r => Math.abs(r.gy) < 1e-6 && r.gx > 0 && r.I0 > 0.4)
    if (labels && row.length > 1) {
      const y0 = cy + R * 1.22
      c.strokeStyle = rgba(P.ink, 0.4)
      c.beginPath()
      c.moveTo(cx, y0)
      c.lineTo(cx + at(row, row.length - 1).gx * scale, y0)
      for (const r of row) {
        c.moveTo(cx + r.gx * scale, y0 - 4)
        c.lineTo(cx + r.gx * scale, y0 + 4)
      }
      c.stroke()
      c.font = font(P, 9.5, s)
      c.fillStyle = rgba(P.ink2, 0.9)
      c.fillText(`|g| ratios ${rowRatios().map(v => v.toFixed(3)).join(' · ')} → τ = ${PHI.toFixed(6)}`, cx, y0 + 16)
    }

    // One indexed reflection per tool call.
    const used = new Set<number>()
    const items = index.update(A, now, f.dt, still, () => {
      let best = -1
      let bv = -1
      acc.forEach((a, j) => {
        if (a > bv && !used.has(j)) {
          bv = a
          best = j
        }
      })
      return { ri: best }
    })
    items.forEach((it) => { used.add(it.item.ri) })
    items.forEach((it, n) => {
      const r = at(ZONE, it.item.ri)
      const [x, y] = pos(r)
      const ag = (now - it.t0) / 1000
      if (!still && ag < 1.6) {
        c.strokeStyle = rgba(P.accent, 1 - ag / 1.6)
        c.lineWidth = 1.5
        c.beginPath()
        c.arc(x, y, 4 + ag * 30 * s, 0, TAU)
        c.stroke()
        c.lineWidth = 1
      }
      c.strokeStyle = rgba(P.ink, 0.85 * it.k)
      c.strokeRect(x - 7, y - 7, 14, 14)
      if (labels) {
        const lab = `(${r.n.join(' ')}) · d ${(A_R / r.g).toFixed(3)} Å · |g| ${(r.g / A_R * 10).toFixed(2)} nm⁻¹`
        c.beginPath()
        c.moveTo(x + 7, y - 7)
        c.lineTo(x + 26 * s, y - 22 * s)
        c.stroke()
        c.font = font(P, 10, s)
        c.fillStyle = rgba(P.lab, it.k)
        c.fillText(n === items.length - 1 && !still ? decode(lab, ag / 0.7, now / 1000) : lab, x + 30 * s, y - 20 * s)
      }
    })

    // Icosahedral cluster, turning.
    const ux3 = w * 0.92
    const uy3 = h * 0.8
    const us = 20 * s + 6
    const ry = A.ph * 0.4
    const rx = 0.55
    const pr = ([x, y, z]: [number, number, number]): [number, number, number] => {
      const x1 = x * Math.cos(ry) + z * Math.sin(ry)
      const z1 = -x * Math.sin(ry) + z * Math.cos(ry)
      const y1 = y * Math.cos(rx) - z1 * Math.sin(rx)
      const d = y * Math.sin(rx) + z1 * Math.cos(rx)
      return [ux3 + x1 * us, uy3 - y1 * us, d]
    }
    const pts = ICOSA.v.map(pr)
    c.strokeStyle = rgba(P.ink, 0.4)
    c.beginPath()
    for (const [i, j] of ICOSA.edges) {
      c.moveTo(at(pts, i)[0], at(pts, i)[1])
      c.lineTo(at(pts, j)[0], at(pts, j)[1])
    }
    c.stroke()
    pts.forEach((p) => {
      c.fillStyle = rgba(P.accent, clamp(0.45 + 0.25 * p[2] / PHI))
      c.beginPath()
      c.arc(p[0], p[1], 2.4 * ms, 0, TAU)
      c.fill()
    })
    footer(f, `e⁻ 200 kV · λ 2.508 pm · precession 1.5° · i-Al₆Mn · zone 5-fold · σ_mosaic ${(sig * 21).toFixed(2)}° · Laue φ ${((phiP * 57.2958) % 360).toFixed(1)}°`)
  }
}
